const upsertRunArtifact = `-- name: UpsertRunArtifact :exec
INSERT INTO run_artifacts (id, run_id, provider, external_artifact_id, provider_artifact_type,
    name, normalized_type, storage_type, resolution_status, metadata)
VALUES (?, ?, ?, ?, ?, ?, ?, 'external', 'pending', NULL)
ON DUPLICATE KEY UPDATE
    provider_artifact_type = VALUES(provider_artifact_type),
    normalized_type = VALUES(normalized_type)
`

type UpsertRunArtifactParams struct {
	ID                   []byte
	RunID                []byte
	Provider             string
	ExternalArtifactID   string
	ProviderArtifactType string
	Name                 string
	NormalizedType       string
}

// Guarded by unique (run_id, external_artifact_id); empty external ids get
// their own row keyed by the generated PK.
func (q *Queries) UpsertRunArtifact(ctx context.Context, arg UpsertRunArtifactParams) error {
	_, err := q.db.ExecContext(ctx, upsertRunArtifact,
		arg.ID,
		arg.RunID,
		arg.Provider,
		arg.ExternalArtifactID,
		arg.ProviderArtifactType,
		arg.Name,
		arg.NormalizedType,
	)
	return err
}
